update cellar.products set source_checked_at = now() where id in ('3e19900e-ca5c-439b-b140-71c8dfa22a69', '4ae55b85-a10a-48e9-aa3f-b4fc5ccd406e');
update cellar.products set source = 'maker', status = 'confirmed', source_url = 'https://www.watchhillwhiskeyco.com/pages/exceptional-series', discontinued = false, catalog_included = catalog_included or is_core_range, rarity = coalesce(rarity, 'allocated'::cellar.rarity), producer = coalesce(producer, 'Watch Hill Proper'), producer_id = coalesce(producer_id, 'e656b67c-0c95-4f85-b2b0-747ba5b2db80'::uuid) where id = '3e19900e-ca5c-439b-b140-71c8dfa22a69' and facts_verified_at is null;
update cellar.products set source = 'maker', status = 'confirmed', source_url = 'https://www.watchhillproper.com/whwc-1', discontinued = false, catalog_included = catalog_included or is_core_range, rarity = coalesce(rarity, 'limited'::cellar.rarity), producer = coalesce(producer, 'Watch Hill Proper'), producer_id = coalesce(producer_id, 'e656b67c-0c95-4f85-b2b0-747ba5b2db80'::uuid) where id = '4ae55b85-a10a-48e9-aa3f-b4fc5ccd406e' and facts_verified_at is null;insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Watch Hill Definitive Series","rar":"limited","f":"Watch Hill Proper","x":"Definitive Series","p":115.0,"ay":12.0,"al":"12 yr","nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":true,"fin":null,"msrp":null,"core":false,"al2":[],"img":null,"u":"https://www.watchhillwhiskeyco.com/pages/definitive-series","pr":"Watch Hill Proper","mk":"e656b67c-0c95-4f85-b2b0-747ba5b2db80"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');